class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        # Convert MiB limit to bytes. Use float->int floor to be safe with
        # fractional MiB values.
        self._limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        # Month -> total bytes that count towards quota in that month.
        self._used = {}
        # Track files that exist, to make delete idempotent-ish and avoid
        # double counting on repeated deletion. Keyed by name -> size.
        self._files = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes == 0:
            raise ValueError("Cannot upload a file of size 0.")
        if size_bytes < 0:
            raise ValueError("File size cannot be negative.")

        current = self._used.get(month, 0)
        if current + size_bytes > self._limit_bytes:
            raise ValueError(
                f"Upload of {size_bytes} bytes would exceed the monthly "
                f"limit of {self._limit_bytes} bytes for {month}."
            )

        # Count the bytes towards the month's quota.
        self._used[month] = current + size_bytes
        # Record/update the file's size.
        self._files[name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        # Deleting a file does not refund quota in the month of deletion.
        # We simply remove the file record so future accounting is sane.
        # Quota already consumed in any month stays consumed.
        self._files.pop(name, None)

    def used_bytes(self, month: str) -> int:
        return self._used.get(month, 0)
